"""Testi per la persona in italiano, inglese e spagnolo.

Il testo italiano è la chiave del catalogo. Con lingua it, o senza lingua
impostata come nella CLI, t() restituisce il testo così com'è. La GUI passa la
lingua al worker nella variabile PARATIA_LANG. I codici di errore non cambiano.
"""
from __future__ import annotations

import os
import re

LINGUE = ("it", "en", "es")
# Il worker nasce in un processo nuovo per ogni richiesta: la lingua scelta nella
# GUI arriva in PARATIA_LANG prima che i moduli costruiscano le proprie tabelle.
_LINGUA = os.environ.get("PARATIA_LANG", "it") if os.environ.get("PARATIA_LANG") in ("it", "en", "es") else "it"

# testo italiano -> (inglese, spagnolo)
